INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64357721', 64357721, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'UNIT PENYELENGGARA BANDAR UDARA TEMINABUAN', 'Penyusunan Dokumen Perencanaan dan Operasi bandar Udara (Rencana Tata Letak Fasilitas Bandar Udara Teminabuan)', 'Jasa Konsultansi', 'Penunjukan Langsung', 'Papua Barat Daya, Sorong Selatan (Kab.)', 1500000000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'PENYUSUNANAN RENCANA TATA LETAK FASILITAS BANDAR UDARA TEMINABUAN', 'Spesifikasi Pekerjaan Penyusunan Rencana Tata Letak Bandar Udara Teminabuan mencakup hal-hal sebagai berikut: a. Analisis pergerakan dan kebutuhan pengguna jasa angkutan udara 1) Pergerakan penumpang tahunan dan jam sibuk; 2) Pergerakan kargo dan pos tahunan dan jam sibuk; 3) Pergerakan pesawat tahunan dan jam sibuk; 4) Jaringan/rute penerbangan masa datang; 5) Pengoperasian jenis/tipe pesawat masa mendatang; 6) Pergerakan/jumlah pekerja, pengunjung serta pengantar dan penjemput, b. Analisis Lokasi (Site) 1) Pengembangan pada areal di sekitar bandar udara; 2) Kondisi atmospherik; 3) Aksesibilitas dengan moda angkutan lain; 4) Ketersediaan lahan bagi pengembangan di masa yang akan datang; 5) Kondisi topografi; 6) Identifikasi dampak lingkungan; 7) Data dukung tanah; 8) Drainase. c. Analisis ruang udara dan pelayanan lalu lintas udara 1) Standard prosedur pendaratan dan lepas; 2) Persyaratan ruang udara (KKOP); 3) Pelayanan lalu lintas udara (air traffic Services); 4) Peralatan navigasi yang akan digunakan. d. Analisis Kapasitas dan Kebutuhan Fasilitas Bandar Udara 1) Kapasitas dan kebutuhan fasilitas sisi udara; 2) Kapasitas dan kebutuhan fasilitas sisi darat; 3) Kapasitas dan kebutuhan fasilitas navigasi penerbangan; 4) Kapasitas dan kebutuhan fasilitas alat bantu pendaratan; 5) Kapasitas dan kebutuhan fasilitas komunikasi penerbangan; 6) Kapasitas dan kebutuhan fasilitas penunjang operasi bandar udara; 7) Kapasitas dan kebutuhan fasilitas, pengamatan penerbangan; 8) Kapasitas dan kebutuhan fasilitas penunjang bandar udara; 9) Kapasitas dan kebutuhan jalan masuk. e. Analisis Tata Letak dan Tata Guna Lahan 1) Konfigurasi bandar udara; 2) Tata letak fasilitas bandar udara; 3) Penggunaan lahan bandar udara; 4) Rencana dan tahapan pembangunan bandar udara f. Analisis Ekonomi 1) Analisis pembandingan dikembangkan atau tidak; 2) Analisis manfaat apabila Bandar udara dikembangkan; 3) Analisis manfaat yang hilang bila tidak dikembangkan; 4) Net Present Value (NPV); 5) Economic Internal Rate of Return (EIRR); 6) Benefit Cost Ratio (BCR); 7) Payback Period. g. Analisis Finansial 1) Net Present Value (NPV); 2) Financial Internal Rate of Return (FIRR); 3) Profitability lndex (Pl); 4) Payback Period. h. Analisa kebutuhan biaya dan Tahapan Pelaksanaan Pembangunan 1) Analisa kebutuhan biaya pembangunan 2) Kesesuaian tahapan fasilitas dan kebutuhan; 3) keserasian kesesuaian tahapan dan operasional bandara, i. Kebutuhan dan Pemanfaatan Lahan 1) Ketersediaan lahan sesuai kebutuhan ultimate; 2) Ketersediaan lahan sesuai pentahapan. j. Kawasan Keselamatan Operasi Penerbangan 1) Standar prosedur pendaratan dan lepas landas; 2) Persyaratam ruang udara (identifikasi KKOP); 3) Pelayanan lalu lintas udara (ATS); 4) Peralatan navigasi yang akan digunakan; 5) Sesuai klasifikasi KKOP (klasifikasi RW); 6) Akurasi referensi ACS dan AES; 7) Akurasi titik koordinat batas kawasan; 8) Akurasi batas/jarak horizontal; 9) Akurasi batas/jarak vertikal.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1502499);
