INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64379856', 64379856, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS KETAHANAN PANGAN, KELAUTAN DAN PERTANIAN', 'Belanja Barang Penyediaan Prasarana Teknologi Bioflock', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 44496217, 'March 2026', 'APBD', 1, 1, '1 Paket', 'Penyediaan Sarana Teknologi Bioflok beserta instalasi berupa: 1. Konstruksi atap dan kolam bioflok (1 paket) 2. Bak Fiber Bioflok termasuk instalasi (1 paket) 3. Pelet Ikan HI PRO VITE 788-2 (6 zak) 4. Pelet Ikan HI PRO VITE 788-3 (6 zak) 5. Probiomix (12 pak) 6. Timbangan digital (1 unit) 7. Serokan (1 unit) 8. Paper water test kit (2 pak) 9. Jaring penutup 10. Papan tulis dan alat tulis (1 paket)', 'Spesifikasi barang Penyediaan Sarana Teknologi Bioflok beserta instalasi berupa: 1. Konstruksi Atap & Kolam Bioflok (Luas = 4x4 M, termasuk pekerjaan Pondasi Cor, Kolom & Rangka Atap Besi Hollow, Penutup Atap UPVC) 2. Bak Fiber Bioflok diameter=2,5 m, tinggi =1 m, ketebalan 4 mm dan kelengkapannya termasuk pengerjaan pengecoran lantai, saluran pipa pembuangan, mesin aerator LP 100 dan instalasi aerasi, instalasi listrik, dan papan nama informasi. 3. Pelet Ikan HI PRO VITE 788-2 Sp. uk. 2 mm, Protein cukup 26-28%, serat lebih tinggi, berat bersih 30 kg, cocok untuk ikan air tawar (gurami dan nila) 4. Pelet Ikan HI PRO VITE 788-3, uk. 3 mm, Protein cukup 26-28%, serat lebih tinggi, berat bersih 30 kg, cocok untuk ikan air tawar (gurami dan nila) 5. Probiomix, bobot 800 grm, Komposisi : karbohidrat, protein, fosfor, zat besi dan mineral mix. Bahan sember makanan dan energi pendukung pertumbuhan dan perkembangan bakteri heterotrof pembetuk flok. Cocok digunakan untuk metode kolam bioflok 6. Timbangan Digital Scale 40 Kg 7. Serokan Spesifikasi: Diameter 60 Cm, Panjang Gagang 150 Cm, Full Ring 8. Water Test, Paper Test Kualitas Air berisi 6 pengujian diantaranya: (pH, KH, GH, CL2, NO2 &NO3), isi 100 strip 9. Jaring bahan PE serbaguna, D30, harga per m2 10. Papan Tulis Spesifikasi: Gantung, Uk 90x120; Spidol White Board Spesifikasi: Bg 12; Penghapus White Board Spesifikasi: Besar', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1506815);
